 Begin TimeMap 	# Conversion between time coordinate systems
    Nin = 1 	# Number of input coordinates
 IsA Mapping 	# Mapping between coordinate systems
    Ntime = 1 	# Number of conversion steps
    Time1 = "MJDTOBEP" 	# Convert MJD to Besselian epoch
    Time1a = 0 	# MJD offset
    Time1b = 0 	# Besselian epoch offset
    Time1c = 0 	# Combined forward offset
    Time1d = 0 	# Combined inverse offset
 End TimeMap
